function integer transform() {
    RegionalSupportPolicyLookup_Record policy = lookup(RegionalSupportPolicyLookup).get($in.0.customer_region);
    integer basePoints;
    decimal escalationAmount;
    boolean restrictedService;
    if (isnull(policy.customer_region)) {
        basePoints = 20;
        escalationAmount = 0D;
        restrictedService = false;
    } else {
        basePoints = policy.standard_priority_points;
        escalationAmount = policy.escalation_amount_inr;
        restrictedService = policy.restricted_service;
    }

    integer priority = basePoints;
    if ($in.0.unresolved_contacts_7d >= 3L) priority += 30;
    if (!isnull($in.0.disputed_amount_inr) && $in.0.disputed_amount_inr > escalationAmount) priority += 20;
    if ($in.0.customer_tenure_months < 6) priority += 15;
    if ($in.0.callback_requested) priority += 10;
    if (startsWith($in.0.service_category, "UPI_")) priority += 10;
    if (priority > 100) priority = 100;

    string priorityLevel;
    if (priority >= 75) priorityLevel = "URGENT";
    else if (priority >= 50) priorityLevel = "PRIORITY";
    else if (priority >= 25) priorityLevel = "ROUTINE";
    else priorityLevel = "STANDARD";

