//#CTL2

function integer transform() {
    $out.0.case_id = $in.0.case_id;
    $out.0.shipper_code = $in.0.shipper_code;

    string legalName = nvl($in.1.legal_name_en, "UNLISTED GCC ACCOUNT");
    decimal depositPct = nvl($in.1.deposit_pct, 12.500D);
    decimal setupQuote = nvl($in.0.setup_quote_aed, 0D);

    boolean hasLicenceExpiry = !isnull($in.0.trade_licence_expiry);
    boolean licenceExpired = hasLicenceExpiry && (!isnull($in.0.planned_go_live) && $in.0.planned_go_live > $in.0.trade_licence_expiry);

    decimal guaranteeDeposit;
    if (!hasLicenceExpiry || licenceExpired) {
        guaranteeDeposit = roundHalfToEven(setupQuote * depositPct / 100D, 2);
    } else {
        switch ($in.0.trade_lane_code) {
            case "UAE-KSA":
            case "OMN-UAE":
                guaranteeDeposit = roundHalfToEven(setupQuote * 5D / 100D, 2);
                break;
            default:
                guaranteeDeposit = 0D;
        }
    }

    $out.0.legal_name_en = legalName;
    $out.0.setup_quote_aed = setupQuote;
    $out.0.guarantee_deposit_aed = guaranteeDeposit;
    $out.0.amount_due_now_aed = setupQuote + guaranteeDeposit;

    return OK;
}
