//#CTL2

function void initGroup(AccountRewardAcc acc) {
    acc.earliest_reward_at = null;
    acc.latest_reward_at = null;
    acc.reward_event_count = 0;
}

function boolean updateGroup(AccountRewardAcc acc) {
    boolean isNewEvent = !isnull($in.0.reward_points)
        && $in.0.reward_points > 0D
        && !isnull($in.0.engagement_code)
        && ($in.0.engagement_code ?= "^SAVE_" || $in.0.engagement_code == "DirectDebitBonus")
        && !isnull($in.0.touchpoint_at);

    if (isNewEvent) {
        date currentTouchpoint = $in.0.touchpoint_at;

        if (isnull(acc.earliest_reward_at) || currentTouchpoint < acc.earliest_reward_at) {
            acc.earliest_reward_at = currentTouchpoint;
        }
        if (isnull(acc.latest_reward_at) || currentTouchpoint > acc.latest_reward_at) {
            acc.latest_reward_at = currentTouchpoint;
        }

        acc.reward_event_count++;
    }

    return false;
}

function boolean finishGroup(AccountRewardAcc acc) {
    return acc.reward_event_count > 0;
}

function integer updateTransform(integer counter, AccountRewardAcc acc) {
    return SKIP;
