function integer transform(integer counter, AccountRewardAcc acc) {
    if (counter > 0) return SKIP;

    $out.0.loyalty_account_ref = $in.0.loyalty_account_ref;
    $out.0.member_number = $in.0.member_number;
    $out.0.first_reward_at = acc.earliest_reward_at;
    $out.0.last_reward_at = acc.latest_reward_at;
