function integer transform() {
    $out.0.roster_line_no = $in.0.roster_line_no;

    if (isnull($in.1.staff_ref)) {
        $out.0.scheduling_action = "HOLD";
        $out.0.credited_duty_hours = 0.0;
        $out.0.compensatory_credit = 0D;
        $out.0.justification_code = "STAFF_RECORD_MISSING";
        return ALL;
    }
    if (isnull($in.2.office_ref)) {
        $out.0.scheduling_action = "HOLD";
        $out.0.credited_duty_hours = 0.0;
        $out.0.compensatory_credit = 0D;
        $out.0.justification_code = "OFFICE_RECORD_MISSING";
        return ALL;
    }

    if ($in.1.appointment_state != "APPOINTED"
        || (!isnull($in.0.duty_day) && !isnull($in.1.service_from)
            && $in.0.duty_day < $in.1.service_from)
        || (!isnull($in.0.duty_day) && !isnull($in.1.service_until)
            && $in.0.duty_day > $in.1.service_until)) {
        $out.0.scheduling_action = "UNASSIGNABLE";
        $out.0.credited_duty_hours = 0.0;
        $out.0.compensatory_credit = 0D;
        $out.0.justification_code = "OUTSIDE_APPOINTMENT";
        return ALL;
    }

    if (!isnull($in.0.duty_class)
        && startsWith($in.0.duty_class, "PUBLIC_COUNTER")
        && $in.2.access_level == "CLOSED") {
        $out.0.scheduling_action = "UNASSIGNABLE";
        $out.0.credited_duty_hours = 0.0;
        $out.0.compensatory_credit = 0D;
        $out.0.justification_code = "COUNTER_ACCESS_RESTRICTED";
        return ALL;
    }

    number creditedHours = $in.2.crisis_desk
        ? round($in.0.planned_duty_hours * 1.25, 2)
        : $in.0.planned_duty_hours;
    $out.0.credited_duty_hours = creditedHours;

    decimal flexBalance = nvl($in.1.flex_time_balance, 0D);
    $out.0.compensatory_credit = flexBalance < creditedHours
        ? flexBalance : creditedHours;

    if (!isnull($in.0.duty_class)
        && startsWith($in.0.duty_class, "CROSS_MUNICIPAL")) {
        $out.0.scheduling_action = "MUNICIPAL_COORDINATION";
        $out.0.justification_code = "CROSS_MUNICIPAL_DUTY";
        return ALL;
    }
