Write a Rollup to aggregate Iberian bank cash shipments grouped by bank_branch_code. Track the total number of shipments and the sum_euro_value for all shipments. Include a shipment in cleared_euro_value and average_euro_value only when its destination_country is either 'ES' or 'PT' and its shipment_status starts with 'CLEARED'. Count shipments requiring review when shipment_status is null or contains 'HOLD'. Retain the latest dispatch_date per bank branch.

PROPOSED CTL2 CODE:
```ctl
//#CTL2

function void initGroup(CashShipmentAccumulator acc) {
    acc.shipment_total = 0;
    acc.sum_euro_value = 0D;
    acc.cleared_euro_value = 0D;
    acc.review_shipment_total = 0L;
    acc.latest_dispatch_date = null;
}

function boolean updateGroup(CashShipmentAccumulator acc) {
    acc.shipment_total = acc.shipment_total + 1;

    if (isnull($in.0.shipment_status) ||
        $in.0.shipment_status == "HOLD" ||
        contains($in.0.shipment_status, "HOLD")) {
        acc.review_shipment_total = acc.review_shipment_total + 1L;
    }

    if (!isnull($in.0.shipment_status) &&
        startsWith($in.0.shipment_status, "CLEARED") &&
        !isnull($in.0.destination_country) &&
        ($in.0.destination_country == "ES" ||
         $in.0.destination_country == "PT")) {
        acc.sum_euro_value += $in.0.euro_value;
        acc.cleared_euro_value += $in.0.euro_value;
    }

    if (!isnull($in.0.dispatch_date) &&
        (isnull(acc.latest_dispatch_date) ||
         $in.0.dispatch_date > acc.latest_dispatch_date)) {
        acc.latest_dispatch_date = $in.0.dispatch_date;
    }

    return false;
}

function boolean finishGroup(CashShipmentAccumulator acc) {
    return true;
}

function integer updateTransform(integer counter, CashShipmentAccumulator acc) {
    return SKIP;
}

function integer transform(integer counter, CashShipmentAccumulator acc) {
    if (counter > 0) return SKIP;

    $out.0.bank_branch_code = $in.0.bank_branch_code;
    $out.0.shipment_total = acc.shipment_total;
    $out.0.average_euro_value = acc.cleared_euro_value == 0D
        ? 0D : acc.cleared_euro_value / acc.shipment_total;
    $out.0.cleared_euro_value = acc.cleared_euro_value;
    $out.0.review_shipment_total = acc.review_shipment_total;
    $out.0.latest_dispatch_date = acc.latest_dispatch_date;
    return ALL;
}
